// Extract and validate incoming webhook data
const data = $json;

if (!data.request_id || !data.user_id || !data.lead_email || !data.lead_name) {
  throw new Error('Missing required fields: request_id, user_id, lead_email, lead_name');
}

return {
  json: {
    request_id: data.request_id,
    user_id: data.user_id,
    lead_name: data.lead_name,
    lead_email: data.lead_email,
    proposal_template: data.proposal_template || 'standard',
    key_points: data.key_points || '',
    pdf_template_url: data.pdf_template_url || null,
    timestamp: new Date().toISOString()
  }
};

// Parse and validate ChatGPT response
const raw = $json.text || $json.message?.content || $json.content || '';

if (!raw) {
  throw new Error('Empty response from ChatGPT');
}

let cleaned = raw.replace(/```json|```/g, '').trim();
const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
if (jsonMatch) cleaned = jsonMatch[0];

cleaned = cleaned
  .replace(/[\u201C\u201D]/g, '"')
  .replace(/[\u2018\u2019]/g, "'");

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Failed to parse ChatGPT proposal JSON: ' + e.message + ' | RAW: ' + cleaned.slice(0, 500));
}

// Ensure valid_until is a proper date
if (!parsed.valid_until) {
  const futureDate = new Date();
  futureDate.setDate(futureDate.getDate() + 30);
  parsed.valid_until = futureDate.toISOString().split('T')[0];
}

return {
  json: {
    proposal_json: parsed,
    generated_at: new Date().toISOString()
  }
};

// Parse validation response
const raw = $json.text || $json.message?.content || $json.content || '';

let cleaned = raw.replace(/```json|```/g, '').trim();
const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
if (jsonMatch) cleaned = jsonMatch[0];

cleaned = cleaned
  .replace(/[\u201C\u201D]/g, '"')
  .replace(/[\u2018\u2019]/g, "'");

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    is_valid: false,
    issues: ['Could not parse validation response'],
    approved: false,
    confidence_score: 0
  };
}

return {
  json: {
    validation: parsed,
    guardrail_errors: parsed.issues || [],
    reviewer_approved: parsed.approved || false,
    confidence_score: parsed.confidence_score || 0
  }
};
